# Use the same complete-case sample for every regression model.
dat &lt;- attitude |&gt;
  select(rating, complaints, learning, raises) |&gt;
  drop_na()

n &lt;- nrow(dat)

3.1. Conduct nested-model F-tests


Code
tests &lt;- anova(mod0, mod1, mod2, mod3)

tests &lt;- tests |&gt;
  as.data.frame() |&gt;
  select(Res.Df, Df, F, `Pr(&gt;F)`) |&gt;
  rename(
    Residual.df = Res.Df,
    Nested.Df = Df,
    Nested.F.stat = F,
    Nested.p.value = `Pr(&gt;F)`
  )
